int main(int argc,char**argv){if(argc!=2)return 1;std::ifstream file(argv[1],std::ios::binary);dfre::AssetBytes raw((std::istreambuf_iterator<char>(file)),{});Test t(raw);std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;if(t.row[0]>=20)return 2;t.setup();auto b=t.bindings();const U op=t.row[0];std::vector<U>a;switch(op){case 0:a={t.row[8],t.row[7]};break;case 2:a={0x1280000,t.row[7],t.row[8],t.row[9]};break;case 1:case 3:case 5:case 7:a={0x1280000};break;case 4:case 6:case 16:a={t.row[9]};break;case 9:a={t.row[8]};break;default:break;}const U f=t.make(sites[op],sizes[op],a);bool failed=false;U result=0;try{result=dfre::mission_netsock_client_worker_call(b,sites[op],f);}catch(const std::runtime_error&){failed=true;}if(t.frames.size()!=1)return 3;std::uint64_t state=1469598103934665603ull;for(auto [at,n]:std::vector<std::pair<U,U>>{{0x10019880,0x426},{0x1280000,0x2000},{0x10006088,4}}){const auto*p=t.image->resolve(at,n);for(U i=0;i<n;++i){state^=p[i];state*=1099511628211ull;}}std::cout<<failed<<' '<<(failed||!(op==0||op==18||op==19)?0:result)<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
